const z = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
if (!z.locales || typeof z.locales.uz !== "function") broken("z.locales.uz is missing");
z.config(z.locales.uz());
const r = z.map(z.string(), z.string()).min(3).safeParse(new Map([["a", "b"]]));
if (r.success) broken("a 1-entry map passed .min(3)");
const issue = r.error.issues[0];
if (issue.code !== "too_small") broken("unexpected issue code " + issue.code);
const msg = issue.message;
console.log("message: " + msg);
if (!msg.includes("3")) broken("message does not mention the minimum: " + msg);
if (!msg.includes("yozuv")) symptom("z.locales.uz too_small message for z.map has no unit yozuv");
console.log("OK: z.locales.uz too_small message for z.map uses the unit yozuv");

